class Spell {
  constructor(name, manaCost) {
    this.name = name;
    this.manaCost = manaCost;
  }

  cast() {
    return `${this.name} spell costs ${this.manaCost} mana.`;
  }
}

// TODO: Create a FireballSpell class that extends Spell
// It should have a 'damage' property and override the 'cast' method.
// The cast method should return: "Fwoosh! [spell name] deals [damage] damage, costing [manaCost] mana."

// TODO: Create a HealSpell class that extends Spell
// It should have a 'healAmount' property and override the 'cast' method.
// The cast method should return: "Shimmer! [spell name] heals for [healAmount] health, costing [manaCost] mana."

class Magician {
  constructor(name) {
    this.name = name;
  }

  performSpell(spell) {
    if (spell instanceof Spell) {
      return `${this.name} casts: ${spell.cast()}`;
    }
    return `${this.name} can only cast spells!`;
  }
}

