class Spell {
  constructor(name, manaCost) {
    this.name = name;
    this.manaCost = manaCost;
  }

  cast() {
    return `${this.name} spell costs ${this.manaCost} mana.`;
  }
}

class FireballSpell extends Spell {
  constructor(name, manaCost, damage) {
    super(name, manaCost);
    this.damage = damage;
  }

  cast() {
    return `Fwoosh! ${this.name} deals ${this.damage} damage, costing ${this.manaCost} mana.`;
  }
}

class HealSpell extends Spell {
  constructor(name, manaCost, healAmount) {
    super(name, manaCost);
    this.healAmount = healAmount;
  }

  cast() {
    return `Shimmer! ${this.name} heals for ${this.healAmount} health, costing ${this.manaCost} mana.`;
  }
}

